CREATE TABLE #People (
    person_id INT IDENTITY PRIMARY KEY,
    first_name NVARCHAR(50) NOT NULL,
    last_name  NVARCHAR(50) NOT NULL
);

INSERT INTO #People (first_name, last_name)
VALUES (N'Ada', N'Lovelace'), (N'Grace', N'Hopper');

CREATE INDEX ix_people_name ON #People (last_name, first_name);

-- Seek: filter starts with the leading key column
SELECT person_id FROM #People WHERE last_name = N'Hopper';

-- Also a seek: both key columns filtered
SELECT person_id FROM #People WHERE last_name = N'Hopper' AND first_name = N'Grace';

-- Not a seek on this index: the leading key column is missing
SELECT person_id FROM #People WHERE first_name = N'Grace';

SELECT
    c.name AS key_column,
    ic.key_ordinal
FROM tempdb.sys.index_columns AS ic
JOIN tempdb.sys.columns AS c ON c.object_id = ic.object_id AND c.column_id = ic.column_id
WHERE ic.object_id = OBJECT_ID('tempdb..#People')
  AND ic.index_id = INDEXPROPERTY(OBJECT_ID('tempdb..#People'), 'ix_people_name', 'IndexId')
ORDER BY ic.key_ordinal;
